/* ---- SECM (v40): security layer for the whole worker ----
   One wrapper around the outer router: security headers + strict CSP (hashes computed from the page itself) on every response,
   a global CSRF/Origin guard, IP/country blocks, emergency lockdown, per-isolate volume limits, Turnstile hooks (off until the
   TURNSTILE_SECRET secret and a site key exist), breached-password check, account lockout, two-step sign-in (TOTP) for site admins
   (required) and instructors/program admins (optional or required by setting), re-authentication for sensitive actions, a security
   event log in D1 (sec_events, with retention), phone/email alerts, the Security Center API (/api/sec/*) and field-level encryption
   helpers for the document vault (globalThis.__SECM.crypto, see security/CRYPTO-API.md).
   Self-contained: uses only env.DB, env.SITE, env.EMAIL (optional), secrets by name, and __W.fetch / PUSH.send when present.
   No KV writes on hot paths (only alerts, max 30/day, and the maintenance/sign-up switches). */
const SECM = (() => {
  const VER = "sec-1.0";
  const enc = new TextEncoder(), dec = new TextDecoder();
  const now = () => Date.now();
