  /* ---------------- schema ---------------- */
  const READY = new WeakSet(); /* per database binding (one per isolate in production) */
  async function init(env) {
    if (READY.has(env.DB)) return;
    await env.DB.batch([
      "CREATE TABLE IF NOT EXISTS sec_events (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, kind TEXT NOT NULL, sev INTEGER NOT NULL, ip TEXT, cc TEXT, asn INTEGER, uid TEXT, who TEXT, path TEXT, detail TEXT, ack INTEGER)",
      "CREATE INDEX IF NOT EXISTS sec_events_at ON sec_events (at)",
      "CREATE INDEX IF NOT EXISTS sec_events_kind ON sec_events (kind, at)",
      "CREATE INDEX IF NOT EXISTS sec_events_ip ON sec_events (ip, at)",
      "CREATE TABLE IF NOT EXISTS sec_kv (k TEXT PRIMARY KEY, v TEXT NOT NULL, at INTEGER)",
      "CREATE TABLE IF NOT EXISTS sec_mfa (user_id TEXT PRIMARY KEY, secret TEXT NOT NULL, created INTEGER NOT NULL, last_step INTEGER, rc TEXT, confirmed INTEGER NOT NULL DEFAULT 0)",
      "CREATE TABLE IF NOT EXISTS sec_ticket (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0, pend TEXT, ctx TEXT)",
