      "CREATE TABLE IF NOT EXISTS sec_reauth (sid TEXT PRIMARY KEY, until INTEGER NOT NULL)",
      "CREATE TABLE IF NOT EXISTS sec_lock (k TEXT PRIMARY KEY, until INTEGER NOT NULL, reason TEXT, by_id TEXT, at INTEGER NOT NULL, n INTEGER NOT NULL DEFAULT 1)",
      "CREATE TABLE IF NOT EXISTS sec_block (k TEXT PRIMARY KEY, kind TEXT NOT NULL, until INTEGER NOT NULL, reason TEXT, by_id TEXT, at INTEGER NOT NULL)",
      "CREATE TABLE IF NOT EXISTS sec_seen (user_id TEXT NOT NULL, kind TEXT NOT NULL, v TEXT NOT NULL, first INTEGER NOT NULL, last INTEGER NOT NULL, PRIMARY KEY (user_id, kind, v))",
