    ts: { siteKey: "", login: "auto", forms: true }, alerts: { push: true, email: "", minSev: 3 },
    lockAfter: 10, lockMinutes: 30, volume: 900, adminMaxHours: 12, adminIdleMin: 60, staffMaxDays: 14, anyMaxDays: 90,
    phiScan: true, mfaAll: false, hipaa: { on: false, at: 0, by: "" } };
