  const eff = C => !C.hipaa || !C.hipaa.on ? C : Object.assign({}, C, { mfaStaff: true, retentionDays: Math.max(C.retentionDays, 2190), adminMaxHours: Math.min(C.adminMaxHours, 8), adminIdleMin: Math.min(C.adminIdleMin, 15), staffMaxDays: 0.5, anyMaxDays: Math.min(C.anyMaxDays, 7), idleAllMin: 30, csp: "enforce", breach: true });
